#include "ksStateMenuActionsTask.h"
#include <iostream>
#include <stdexcept>
using T=ks::StateMenuActionsTask;using S=T::Stage;using E=T::Exit;
void check(bool v){if(!v)throw std::runtime_error("Menu action property differs");}
int main(){try{uint64_t cases=0,intervals=0;
 auto run=[&](T& t,unsigned page,unsigned special,unsigned edit,unsigned screen,unsigned subpage,unsigned mode,unsigned part,bool gate){unsigned reads=0,writes=0,children=0;while(!t.complete()){const auto stage=t.stage();const auto cost=t.nextClocks(),r=reads,w=writes;auto read=[&](T::Read f)->uint32_t{++reads;switch(f){case T::Read::UiPage:return page;case T::Read::Special:return special;case T::Read::Edit:return edit;case T::Read::Screen:return screen;case T::Read::Page:return subpage;case T::Read::Mode:return mode;case T::Read::Part:return part;default:return page;}};auto write=[&](T::Write,uint8_t){++writes;};check(cost&&!t.advanceBefore(cost-1,read,write)&&stage==t.stage()&&r==reads&&w==writes);check(t.advanceBefore(cost,read,write)==cost);++intervals;if(t.awaitingChild()){++children;check(t.resumeChild(stage==S::ObserveCalibrationGate?gate:bool(edit)));}}return children;};
 for(auto kind:{T::Kind::Previous,T::Kind::Next})for(unsigned pressed:{0u,1u})for(unsigned page=0;page<256;++page)for(unsigned special:{0u,1u,255u})for(unsigned edit:{0u,1u,255u}){T t(kind,0,bool(pressed));run(t,page,special,edit,0,0,0,0,false);const bool next=kind==T::Kind::Next;const auto expected=!pressed?E::ReleaseNavigation:page==2?(next?E::NextName:E::PreviousName):special?(next?E::NextSpecial:E::PreviousSpecial):!edit?E::Edit:next?E::NextProgram:E::PreviousProgram;check(t.exit()==expected);++cases;}
 for(unsigned page=0;page<256;++page)for(unsigned screen:{0u,1u,9u,255u})for(unsigned subpage:{0u,1u,2u,128u,255u})for(unsigned edit:{0u,1u})for(unsigned mode:{0u,1u})for(unsigned part:{0u,1u})for(unsigned gate:{0u,1u}){T t(T::Kind::Store);run(t,page,0,edit,screen,subpage,mode,part,bool(gate));const auto expected=gate|| (edit&&screen==0)?E::Notice:edit&&screen==9?(subpage==0?E::FirstPage:subpage==1?E::SecondPage:E::None):page==0?E::ProgramStore:page==1?E::MultiStore:page==3?E::PanelStore:!mode||part?E::PartStore:E::CommonStore;check(t.exit()==expected);++cases;}
 for(unsigned event=0;event<65536;++event){T t(T::Kind::Dispatch,uint16_t(event));run(t,0,0,0,0,0,0,0,false);check(t.index()==uint8_t(event<<2)&&t.exit()==E::Handler);++cases;}
 for(unsigned v=0;v<256;++v)for(bool pressed:{false,true}){T t(T::Kind::Toggle,0,pressed);run(t,v,0,0,0,0,0,0,false);check(t.exit()==(pressed?E::RefreshToggle:E::Release));if(pressed)check(t.toggle()==(v^1));++cases;}
 std::cout<<"PASS: "<<cases<<" menu-action policies / "<<intervals<<" intervals; all navigation pages, Store routes, dispatch word events, toggle bytes, child flags and insufficient budgets\n";return 0;
}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
